  fun ms' => exists (t0' t1' t2' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR (Z_to_bv 64 qenq_refill_ret) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0' t1' t2'
